def expand_service_faq(path, qa_pairs):
    with open(path) as f:
        content = f.read()

    for question, answer, _ in qa_pairs:
        q_city = question  # no city substitution for service pages
        a_text = answer

        # Replace in JSON-LD
        json_pat = r'"name"\s*:\s*"' + re.escape(q_city) + r'"[\s\S]*?"acceptedAnswer"\s*:\s*\{[^}]*?"text"\s*:\s*"'
        m = re.search(json_pat, content)
        if m:
            start = m.end()
            end = content.index('"', start)
            content = content[:start] + a_text + content[end:]
        else:
            # Try with HTML entity apostrophe
            q_html = q_city.replace("'", "&#8217;").replace("’", "&#8217;")
            json_pat2 = r'"name"\s*:\s*"' + re.escape(q_html) + r'"[\s\S]*?"acceptedAnswer"\s*:\s*\{[^}]*?"text"\s*:\s*"'
            m = re.search(json_pat2, content)
            if m:
                start = m.end()
                end = content.index('"', start)
                content = content[:start] + a_text + content[end:]
            else:
                print(f"  WARNING: Could not find Q in JSON: {q_city[:50]}")

        # Replace in visible FAQ (try with both straight apostrophe and HTML entity)
        q_visible = q_city.replace("'", "&#8217;").replace("'", "&#8217;")
        q_visible_raw = q_city.replace("'", "'").replace("'", "'")
        visible_re_str = re.escape(q_visible_raw.rstrip()).replace("'", "(?:'|&#8217;|')")
        visible_pat = r'(<summary class="faq-q">)' + visible_re_str + r'\s*(<span class="faq-chevron">▾</span></summary><div class="faq-a">)(.*?)(</div>)'
        m = re.search(visible_pat, content)
        if m:
            content = re.sub(visible_pat, lambda m2, a=a_text: m2.group(1) + q_visible_raw.rstrip() + ' ' + m2.group(2) + a_text + m2.group(4), content, count=1)
        else:
            print(f"  WARNING: Could not find Q in visible: {q_visible[:50]}")

    with open(path, 'w') as f:
        f.write(content)

for fname, qas in all_pages:
    path = os.path.join(root, fname)
    if os.path.exists(path):
        print(f"Processing {fname} ({len(qas)} Qs)...")
        expand_service_faq(path, qas)
    else:
        print(f"SKIP: {fname} not found")

print("Service FAQ expansion complete.")
